function canAutoRefresh(){
 const editing=["INPUT","SELECT","TEXTAREA"].includes(document.activeElement?.tagName);
 return !preview&&state.session?.connected&&!document.hidden&&["home","trade","positions"].includes(state.tab)&&!document.querySelector(".trade-sheet.open")&&!editing;
}
setInterval(()=>{const interval=(state.session?.refreshSeconds||20)*1000;if(canAutoRefresh()&&Date.now()-state.lastRefreshAt>=interval)load({silent:true})},3000);
document.addEventListener("visibilitychange",()=>{if(!document.hidden&&canAutoRefresh()&&Date.now()-state.lastRefreshAt>5000)load({silent:true})});
load();

function renderOnboarding(){
 document.querySelectorAll("[data-onboarding-step]").forEach(step=>step.hidden=Number(step.dataset.onboardingStep)!==state.onboardingStep);
 document.querySelectorAll("[data-onboarding-dot]").forEach(dot=>dot.classList.toggle("active",Number(dot.dataset.onboardingDot)<=Math.min(state.onboardingStep,4)));
}
function showOnboarding(show){
 $("#onboarding").hidden=!show;
 $("main").hidden=show;
 $(".bottom-nav").hidden=show;
 $("#refresh").hidden=show;
 if(show){$("#mode").textContent="ACCOUNT SETUP";renderOnboarding()}
}
document.addEventListener("click",e=>{
 const next=e.target.closest("[data-onboarding-next]");if(next){state.onboardingStep=Math.min(3,state.onboardingStep+1);renderOnboarding();scrollTo({top:0,behavior:"smooth"});return}
 const back=e.target.closest("[data-onboarding-back]");if(back){state.onboardingStep=Math.max(0,state.onboardingStep-1);renderOnboarding();scrollTo({top:0,behavior:"smooth"});return}
 if(e.target.id==="finishOnboarding"){showOnboarding(false);load()}
});
$("#connectForm").addEventListener("submit",async e=>{
 e.preventDefault();
 const input=$("#apiKey"),button=$("#connectButton"),error=$("#connectError");
 button.disabled=true;button.textContent="Checking your connection…";error.textContent="";
 try{
  const pending=api("/api/connect",{method:"POST",body:JSON.stringify({apiKey:input.value})});
  input.value="";
  await pending;state.session=null;state.onboardingStep=4;renderOnboarding();toast("Account connected. Choose your Guardian mode.");
 }catch(err){error.textContent=err.message}
 finally{button.disabled=false;button.textContent="Validate and connect"}
});
