$("#saveOnboardingGuardrails").addEventListener("click",async()=>{
 const guardianMode=$("#onboardingGuardianMode").value,maxRiskUsd=guardianMode==="off"?100000:Number($("#onboardingMaxRisk").value),maxLossRoomUsagePercent=guardianMode==="off"?100:Number($("#onboardingLossRoom").value);
 if(guardianMode!=="off"&&(!Number.isFinite(maxRiskUsd)||maxRiskUsd<1||maxRiskUsd>100000))return toast("Enter your maximum risk per trade.");
 if(guardianMode!=="off"&&(!Number.isFinite(maxLossRoomUsagePercent)||maxLossRoomUsagePercent<1||maxLossRoomUsagePercent>100))return toast("Enter a loss-room percentage from 1 to 100.");
 try{await api("/api/settings/guardian",{method:"POST",body:JSON.stringify({guardianMode,maxRiskUsd,maxLossRoomUsagePercent,alertsEnabled:true})});state.onboardingStep=5;renderOnboarding()}catch(error){toast(error.message)}
});
